import time

from moler.config import load_config
from moler.device import DeviceFactory
from moler.exceptions import CommandFailure, CommandTimeout
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer

from taf.ue.iphone.data_transfer.utils.ip_addr_selector import get_iphone_ip
from taf.ue.iphone.exceptions import InfiniteLoopDetected, IperfStartFailed


class IphonePingDataTransfer(LteDataTransfer):
    """IphonePingDataTransfer class"""

    def __init__(self, name, ue_pc, iphone_name, dt_definition, configuration):
        """

        :param name: alias of data transfer
        :param ue_pc: Rpc object responsible for HTTP/HTTPS request
        :param iphone_name: id of iphone, e.g. 00008101-000144860011401E
        :param dt_definition: object containing data transfer's details
        :param configuration: UE configuration from config yaml file
        """
        super().__init__(name, dt_definition, configuration)
        self.dt_id = None
        self.iphone_name = iphone_name
        self.ue_pc = ue_pc

        self.dt_config = self._build_dt_config(dt_definition, configuration)
        self.moler_device = self._create_moler_device()

        self.ping_cmd = None

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        if self.dt_config["direction"] == "ul":
            iphone_ping_options = self._build_iphone_ping_options()
            destination = self.dt_config['bind_interface_ip']
            self.logger.info(f"ping cmd (iphone): ping {iphone_ping_options} {destination}")
            self.ue_pc.start_data_transfer(ue_id=self.iphone_name,
                                           data_transfer_id=self.dt_id,
                                           data_transfer_cmd=f"{destination} {iphone_ping_options}",
                                           data_transfer_class="iphoneping")
        elif self.dt_config["direction"] == "dl":
            appserver_ping_options = self._build_app_server_ping_options()
            destination = get_iphone_ip(ue_pc=self.ue_pc, ue_id=self.iphone_name, logger=self.logger,
                                        apn=self.dt_config['apn'])
            self.logger.info(f"ping cmd (app server): ping {appserver_ping_options} {destination}")
            self.ping_cmd = self.moler_device.get_cmd(cmd_name="ping", cmd_params={'destination': destination,
                                                                                   'options': appserver_ping_options})
            self.ping_cmd.start(timeout=self.dt_config["duration"] + 3)
            if self.ping_cmd.done():
                raise IperfStartFailed(f"start cmd \"ping {appserver_ping_options}\" failed")

    def stop(self):
        """
        Stops already running data transfer.
        :return: None
        """
        if self.dt_config["direction"] == "ul":
            self.logger.debug("stopping data transfer on iphone")
            self.ue_pc.stop_data_transfer(ue_id=self.iphone_name, data_transfer_id=self.dt_id)
        elif self.dt_config["direction"] == "dl":
            self.logger.debug("stopping data transfer on appserver")
            try:
                self.ping_cmd.break_cmd()
                self.ping_cmd.await_done(timeout=10)
            except CommandFailure:
                self.logger.warning("moler raised CommandFailure during breaking ping command")
            except CommandTimeout:
                self.logger.warning("moler raised CommandTimeout during breaking ping command")

    def await_finish(self):
        """
        Waits until this data transfer finish.
        :return: None
        """
        if not self.dt_config['count']:
            raise InfiniteLoopDetected("You have run ping cmd endlessly (without \'count\' param) and you are trying "
                                       "wait for the end of it.")
        is_cmd_done = False
        while not is_cmd_done:
            if self.dt_config["direction"] == "ul":
                data_transfer_state = self.ue_pc.get_data_transfer_state(ue_id=self.iphone_name,
                                                                         data_transfer_id=self.dt_id)
                is_cmd_done = data_transfer_state == 'finished'
                time.sleep(3)  # to avoid to many HTTP requests
            elif self.dt_config["direction"] == "dl":
                is_cmd_done = self.ping_cmd.done()
                time.sleep(1)

    def get_data_transfer_statistics(self, **kwargs):
        """
        Returns data transfer statistics.
        :return: dict with ping statistics
        """
        ping_statistics = None
        if self.dt_config["direction"] == "ul":
            ping_statistics = self.ue_pc.get_data_transfer_output(ue_id=self.iphone_name, data_transfer_id=self.dt_id)
        elif self.dt_config["direction"] == "dl":
            ping_statistics = self.ping_cmd.current_ret
        return ping_statistics

    def release_data_transfer(self):
        # TODO: Implement this method if needed
        pass

    def get_average_throughput(self, omit=0, end=0, tput_collection_src="ping"):
        """Not Implemented"""
        raise NotImplementedError

    def is_running(self):
        """Not Implemented"""
        raise NotImplementedError

    def check_data_transfer(self):
        """Not Implemented"""
        raise NotImplementedError

    def reset_statistics(self):
        """Not Implemented"""
        raise NotImplementedError

    def get_datagram_loss(self):
        """Not Implemented"""
        raise NotImplementedError

    # private methods ##############################
    def _create_moler_device(self):
        moler_app_server_config = self._create_app_server_moler_dev_config()
        load_config(config=moler_app_server_config, config_type='dict')
        moler_device = DeviceFactory.get_device(name=self.name, initial_state="UNIX_REMOTE")
        return moler_device

    def _create_app_server_moler_dev_config(self):
        app_server_config = {
            'DEVICES': {
                self.name: {
                    'DEVICE_CLASS': 'moler.device.unixremote.UnixRemote',
                    'CONNECTION_HOPS': {
                        'UNIX_LOCAL': {
                            'UNIX_REMOTE': {
                                'execute_command': 'ssh',
                                'command_params': {
                                    'expected_prompt': self.dt_config['prompt'],
                                    'host': self.dt_config['host'],
                                    'login': self.dt_config['login'],
                                    'password': self.dt_config['password'],
                                    'allowed_newline_after_prompt': True}}}}},
            }}
        self.logger.debug(f"moler device (app server) configuration: {app_server_config}")
        return app_server_config

    def _build_dt_config(self, dt_definition, configuration):
        dt_config = {
            'host': configuration['data_transfer']['ping']['app_server']['address'],
            'password': configuration['data_transfer']['ping']['app_server']['password'],
            'login': configuration['data_transfer']['ping']['app_server']['user'],
            'prompt': configuration['data_transfer']['ping']['app_server']['expected_prompt'],
            'bind_interface_ip': configuration['data_transfer']['ping']['app_server']['bind_interface_ip'],
            'duration': dt_definition.duration if dt_definition.duration != 863913600.0 else 2596000.0,
            'direction': dt_definition.direction,
            'count': dt_definition.protocol_details.get('count', None),
            'apn': dt_definition.protocol_details.get('apn', None)
        }
        self.dt_id = "{}".format(dt_config['direction'])
        self.logger.debug(f"dt_config: {dt_config}")
        return dt_config

    def _build_app_server_ping_options(self):
        ping_options = ""
        ping_options = self._build_common_ping_options(ping_options)
        return ping_options

    def _build_iphone_ping_options(self):
        """
        usage: ping [-AaDdfnoQqRrv] [-c count] [-G sweepmaxsize]
                    [-g sweepminsize] [-h sweepincrsize] [-i wait]
                    [-l preload] [-M mask | time] [-m ttl] [-p pattern]
                    [-S src_addr] [-s packetsize] [-t timeout][-W waittime]
                    [-z tos] host
               ping [-AaDdfLnoQqRrv] [-c count] [-I iface] [-i wait]
                    [-l preload] [-M mask | time] [-m ttl] [-p pattern] [-S src_addr]
                    [-s packetsize] [-T ttl] [-t timeout] [-W waittime]
                    [-z tos] mcast-group
        Apple specific options (to be specified before mcast-group or host like all options)
                    -b boundif           # bind the socket to the interface
                    -k traffic_class     # set traffic class socket option
                    -K net_service_type  # set traffic class socket options
                    -apple-connect       # call connect(2) in the socket
                    -apple-time          # display current time
        """
        ping_options = ""
        ping_options = self._build_common_ping_options(ping_options)
        return ping_options

    def _build_common_ping_options(self, ping_options):
        ping_options += "-c {} ".format(self.dt_config['count']) if self.dt_config['count'] else ""
        return ping_options
